mapper.select:
select
    id
from b_xiecheng_colliding_data_contrast
where is_delete = 1
     and update_time < #{startTime}
order by update_time asc limit #{size};

mapper.delete:
delete from b_xiecheng_colliding_data_contrast
where id in

    #{id}

mapper.select:
select tid,cell  from  #{tableName} a left join b_xiecheng_colliding_data_contrast b
                 on a.cell  = b.cell_sha256_code_list and b.is_delete = 0 where #{filterScore}
                                                                             and b.id is null
limit #{xieChengCleanLimitCount}

select a.id  from  b_xiecheng_colliding_data_loop_cycle a left join b_xiecheng_colliding_data_contrast b
            on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_delete = 0
           where   b.id is null and a.is_delete =0    limit #{xieChengContrastCount}

select  b.id from  b_xiecheng_colliding_data_loop_cycle a  join b_xiecheng_colliding_data_contrast b
                                                                  on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_delete = 0
where a.is_delete =0 limit #{xieChengContrastCount}

select  a.cell_sha256_code_list,a.package_id from  b_xiecheng_colliding_data_contrast a left  join b_xiecheng_colliding_data_rob b
                                                                on a.cell_sha256_code_list  = b.cell_sha256_code_list and b.is_delete = 0
where a.is_delete =0 and b.id is null limit #{xieChengContrastCount}
